7	import * as fs from 'node:fs';
8	import * as path from 'node:path';
9	import ignore, { type Ignore } from 'ignore';
10	
11	export interface GitIgnoreFilter {
12	  isIgnored(filePath: string): boolean;
13	}
14	
15	export class GitIgnoreParser implements GitIgnoreFilter {
16	  private projectRoot: string;
17	  private cache: Map<string, Ignore> = new Map();
18	  private globalPatterns: Ignore | undefined;
19	  private processedExtraPatterns: Ignore;
20	
21	  constructor(
22	    projectRoot: string,
23	    private readonly extraPatterns?: string[],
24	  ) {
25	    this.projectRoot = path.resolve(projectRoot);
26	    this.processedExtraPatterns = ignore();
27	    if (this.extraPatterns) {
28	      // extraPatterns are assumed to be from project root (like .geminiignore)
29	      this.processedExtraPatterns.add(
30	        this.processPatterns(this.extraPatterns, '.'),
31	      );
32	    }
33	  }
34	
35	  private loadPatternsForFile(patternsFilePath: string): Ignore {
36	    let content: string;
37	    try {
38	      content = fs.readFileSync(patternsFilePath, 'utf-8');
39	    } catch (_error) {
40	      return ignore();
41	    }
42	
43	    const isExcludeFile = patternsFilePath.endsWith(
44	      path.join('.git', 'info', 'exclude'),
45	    );
46	
47	    const relativeBaseDir = isExcludeFile
48	      ? '.'
49	      : path
50	          .dirname(path.relative(this.projectRoot, patternsFilePath))
51	          .split(path.sep)
52	          .join(path.posix.sep);
53	
54	    const rawPatterns = content.split('\n');
55	    return ignore().add(this.processPatterns(rawPatterns, relativeBaseDir));
56	  }
57	
58	  private processPatterns(
59	    rawPatterns: string[],
60	    relativeBaseDir: string,
61	  ): string[] {
62	    return rawPatterns
63	      .map((p) => p.trimStart())
64	      .filter((p) => p !== '' && !p.startsWith('#'))
65	      .map((p) => {
66	        const isNegative = p.startsWith('!');
67	        if (isNegative) {
68	          p = p.substring(1);
69	        }
70	
71	        const isAnchoredInFile = p.startsWith('/');
72	        if (isAnchoredInFile) {
73	          p = p.substring(1);
74	        }
75	
76	        // An empty pattern can result from a negated pattern like `!`,
77	        // which we can ignore.
78	        if (p === '') {
79	          return '';
80	        }
81	
82	        let newPattern = p;
83	        if (relativeBaseDir && relativeBaseDir !== '.') {
84	          // Only in nested .gitignore files, the patterns need to be modified according to:
85	          // - If `a/b/.gitignore` defines `/c` then it needs to be changed to `/a/b/c`
86	          // - If `a/b/.gitignore` defines `c` then it needs to be changed to `/a/b/**/c`
87	          // - If `a/b/.gitignore` defines `c/d` then it needs to be changed to `/a/b/c/d`
88	
89	          if (!isAnchoredInFile && !p.includes('/')) {
90	            // If no slash and not anchored in file, it matches files in any
91	            // subdirectory.
92	            newPattern = path.posix.join('**', p);
93	          }
94	
95	          // Prepend the .gitignore file's directory.
96	          newPattern = path.posix.join(relativeBaseDir, newPattern);
97	
98	          // Anchor the pattern to a nested gitignore directory.
99	          if (!newPattern.startsWith('/')) {
100	            newPattern = '/' + newPattern;
101	          }
102	        }
103	
104	        // Anchor the pattern if originally anchored
105	        if (isAnchoredInFile && !newPattern.startsWith('/')) {
106	          newPattern = '/' + newPattern;
107	        }
108	
109	        if (isNegative) {
110	          newPattern = '!' + newPattern;
111	        }
112	
113	        return newPattern;
114	      })
115	      .filter((p) => p !== '');
116	  }
117	
118	  isIgnored(filePath: string): boolean {
119	    if (!filePath || typeof filePath !== 'string') {
120	      return false;
121	    }
122	
123	    const absoluteFilePath = path.resolve(this.projectRoot, filePath);
124	    if (!absoluteFilePath.startsWith(this.projectRoot)) {
125	      return false;
126	    }
127	
128	    try {
129	      const resolved = path.resolve(this.projectRoot, filePath);
130	      const relativePath = path.relative(this.projectRoot, resolved);
131	
132	      if (relativePath === '' || relativePath.startsWith('..')) {
133	        return false;
134	      }
135	
136	      // Even in windows, Ignore expects forward slashes.
137	      const normalizedPath = relativePath.replace(/\\/g, '/');
138	
139	      if (normalizedPath.startsWith('/') || normalizedPath === '') {
140	        return false;
141	      }
142	
143	      const ig = ignore();
144	
145	      // Always ignore .git directory
146	      ig.add('.git');
147	
148	      // Load global patterns from .git/info/exclude on first call
149	      if (this.globalPatterns === undefined) {
150	        const excludeFile = path.join(
151	          this.projectRoot,
152	          '.git',
153	          'info',
154	          'exclude',
155	        );
156	        this.globalPatterns = fs.existsSync(excludeFile)
157	          ? this.loadPatternsForFile(excludeFile)
158	          : ignore();
159	      }
160	      ig.add(this.globalPatterns);
161	
162	      const pathParts = relativePath.split(path.sep);
163	
164	      const dirsToVisit = [this.projectRoot];
165	      let currentAbsDir = this.projectRoot;
166	      // Collect all directories in the path
167	      for (let i = 0; i < pathParts.length - 1; i++) {
168	        currentAbsDir = path.join(currentAbsDir, pathParts[i]);
169	        dirsToVisit.push(currentAbsDir);
170	      }
171	
172	      for (const dir of dirsToVisit) {
173	        const relativeDir = path.relative(this.projectRoot, dir);
174	        if (relativeDir) {
175	          const normalizedRelativeDir = relativeDir.replace(/\\/g, '/');
176	          const igPlusExtras = ignore()
177	            .add(ig)
178	            .add(this.processedExtraPatterns); // takes priority over ig patterns
179	          if (igPlusExtras.ignores(normalizedRelativeDir)) {
180	            // This directory is ignored by an ancestor's .gitignore.
181	            // According to git behavior, we don't need to process this
182	            // directory's .gitignore, as nothing inside it can be
183	            // un-ignored.
184	            break;
185	          }
186	        }
187	
188	        if (this.cache.has(dir)) {
189	          const patterns = this.cache.get(dir);
190	          if (patterns) {
191	            ig.add(patterns);
192	          }
193	        } else {
194	          const gitignorePath = path.join(dir, '.gitignore');
195	          if (fs.existsSync(gitignorePath)) {
196	            const patterns = this.loadPatternsForFile(gitignorePath);
197	
198	            this.cache.set(dir, patterns);
199	            ig.add(patterns);
200	          } else {
201	            this.cache.set(dir, ignore());
202	          }
203	        }
204	      }
205	
206	      // Apply extra patterns (e.g. from .geminiignore) last for precedence
207	      ig.add(this.processedExtraPatterns);
208	
209	      return ig.ignores(normalizedPath);
210	    } catch (_error) {
211	      return false;
212	    }
213	  }
214	}
