7	import * as fs from 'node:fs';
8	import * as path from 'node:path';
9	import ignore from 'ignore';
10	import { debugLogger } from './debugLogger.js';
11	
12	export interface IgnoreFileFilter {
13	  isIgnored(filePath: string): boolean;
14	  getPatterns(): string[];
15	  getIgnoreFilePaths(): string[];
16	  hasPatterns(): boolean;
17	}
18	
19	/**
20	 * An ignore file parser that reads the ignore files from the project root.
21	 */
22	export class IgnoreFileParser implements IgnoreFileFilter {
23	  private projectRoot: string;
24	  private patterns: string[] = [];
25	  private ig = ignore();
26	  private readonly fileNames: string[];
27	
28	  constructor(
29	    projectRoot: string,
30	    // The order matters: files listed earlier have higher priority.
31	    // It can be a single file name/pattern or an array of file names/patterns.
32	    input: string | string[],
33	    isPatterns = false,
34	  ) {
35	    this.projectRoot = path.resolve(projectRoot);
36	    if (isPatterns) {
37	      this.fileNames = [];
38	      const patterns = Array.isArray(input) ? input : [input];
39	      this.patterns.push(...patterns);
40	      this.ig.add(patterns);
41	    } else {
42	      this.fileNames = Array.isArray(input) ? input : [input];
43	      this.loadPatternsFromFiles();
44	    }
45	  }
46	
47	  private loadPatternsFromFiles(): void {
48	    // Iterate in reverse order so that the first file in the list is processed last.
49	    // This gives the first file the highest priority, as patterns added later override earlier ones.
50	    for (const fileName of [...this.fileNames].reverse()) {
51	      const patterns = this.parseIgnoreFile(fileName);
52	      this.patterns.push(...patterns);
53	      this.ig.add(patterns);
54	    }
55	  }
56	
57	  private parseIgnoreFile(fileName: string): string[] {
58	    const patternsFilePath = path.join(this.projectRoot, fileName);
59	    let content: string;
60	    try {
61	      content = fs.readFileSync(patternsFilePath, 'utf-8');
62	    } catch (_error) {
63	      debugLogger.debug(
64	        `Ignore file not found: ${patternsFilePath}, continue without it.`,
65	      );
66	      return [];
67	    }
68	
69	    debugLogger.debug(`Loading ignore patterns from: ${patternsFilePath}`);
70	
71	    return (content ?? '')
72	      .split('\n')
73	      .map((p) => p.trim())
74	      .filter((p) => p !== '' && !p.startsWith('#'));
75	  }
76	
77	  isIgnored(filePath: string): boolean {
78	    if (this.patterns.length === 0) {
79	      return false;
80	    }
81	
82	    if (!filePath || typeof filePath !== 'string') {
83	      return false;
84	    }
85	
86	    if (
87	      filePath.startsWith('\\') ||
88	      filePath === '/' ||
89	      filePath.includes('\0')
90	    ) {
91	      return false;
92	    }
93	
94	    const resolved = path.resolve(this.projectRoot, filePath);
95	    const relativePath = path.relative(this.projectRoot, resolved);
96	
97	    if (relativePath === '' || relativePath.startsWith('..')) {
98	      return false;
99	    }
100	
101	    // Even in windows, Ignore expects forward slashes.
102	    const normalizedPath = relativePath.replace(/\\/g, '/');
103	
104	    if (normalizedPath.startsWith('/') || normalizedPath === '') {
105	      return false;
106	    }
107	
108	    return this.ig.ignores(normalizedPath);
109	  }
110	
111	  getPatterns(): string[] {
112	    return this.patterns;
113	  }
114	
115	  getIgnoreFilePaths(): string[] {
116	    return this.fileNames
117	      .slice()
118	      .reverse()
119	      .map((fileName) => path.join(this.projectRoot, fileName))
120	      .filter((filePath) => fs.existsSync(filePath));
121	  }
122	
123	  /**
124	   * Returns true if at least one ignore file exists and has patterns.
125	   */
126	  hasPatterns(): boolean {
127	    return this.patterns.length > 0;
128	  }
129	}
