1	/**
2	 * @license
3	 * Copyright 2025 Google LLC
4	 * SPDX-License-Identifier: Apache-2.0
5	 */
6	
7	import {
8	  GitIgnoreParser,
9	  type GitIgnoreFilter,
10	} from '../utils/gitIgnoreParser.js';
11	import {
12	  IgnoreFileParser,
13	  type IgnoreFileFilter,
14	} from '../utils/ignoreFileParser.js';
15	import { isGitRepository } from '../utils/gitUtils.js';
16	import { GEMINI_IGNORE_FILE_NAME } from '../config/constants.js';
17	import fs from 'node:fs';
18	import * as path from 'node:path';
19	
20	export interface FilterFilesOptions {
21	  respectGitIgnore?: boolean;
22	  respectGeminiIgnore?: boolean;
23	  customIgnoreFilePaths?: string[];
24	}
25	
26	export interface FilterReport {
27	  filteredPaths: string[];
28	  ignoredCount: number;
29	}
30	
31	export class FileDiscoveryService {
32	  private gitIgnoreFilter: GitIgnoreFilter | null = null;
33	  private geminiIgnoreFilter: IgnoreFileFilter | null = null;
34	  private customIgnoreFilter: IgnoreFileFilter | null = null;
35	  private combinedIgnoreFilter: GitIgnoreFilter | IgnoreFileFilter | null =
36	    null;
37	  private defaultFilterFileOptions: FilterFilesOptions = {
38	    respectGitIgnore: true,
39	    respectGeminiIgnore: true,
40	    customIgnoreFilePaths: [],
41	  };
42	  private projectRoot: string;
43	
44	  constructor(projectRoot: string, options?: FilterFilesOptions) {
45	    this.projectRoot = path.resolve(projectRoot);
46	    this.applyFilterFilesOptions(options);
47	    if (isGitRepository(this.projectRoot)) {
48	      this.gitIgnoreFilter = new GitIgnoreParser(this.projectRoot);
49	    }
50	    this.geminiIgnoreFilter = new IgnoreFileParser(
51	      this.projectRoot,
52	      GEMINI_IGNORE_FILE_NAME,
53	    );
54	    if (this.defaultFilterFileOptions.customIgnoreFilePaths?.length) {
55	      this.customIgnoreFilter = new IgnoreFileParser(
56	        this.projectRoot,
57	        this.defaultFilterFileOptions.customIgnoreFilePaths,
58	      );
59	    }
60	
61	    if (this.gitIgnoreFilter) {
62	      const geminiPatterns = this.geminiIgnoreFilter.getPatterns();
63	      const customPatterns = this.customIgnoreFilter
64	        ? this.customIgnoreFilter.getPatterns()
65	        : [];
66	      // Create combined parser: .gitignore + .geminiignore + custom ignore
67	      this.combinedIgnoreFilter = new GitIgnoreParser(
68	        this.projectRoot,
69	        // customPatterns should go the last to ensure overwriting of geminiPatterns
70	        [...geminiPatterns, ...customPatterns],
71	      );
72	    } else {
73	      // Create combined parser when not git repo
74	      const geminiPatterns = this.geminiIgnoreFilter.getPatterns();
75	      const customPatterns = this.customIgnoreFilter
76	        ? this.customIgnoreFilter.getPatterns()
77	        : [];
78	      this.combinedIgnoreFilter = new IgnoreFileParser(
79	        this.projectRoot,
80	        [...geminiPatterns, ...customPatterns],
81	        true,
82	      );
83	    }
84	  }
85	
86	  private applyFilterFilesOptions(options?: FilterFilesOptions): void {
87	    if (!options) return;
88	
89	    if (options.respectGitIgnore !== undefined) {
90	      this.defaultFilterFileOptions.respectGitIgnore = options.respectGitIgnore;
91	    }
92	    if (options.respectGeminiIgnore !== undefined) {
93	      this.defaultFilterFileOptions.respectGeminiIgnore =
94	        options.respectGeminiIgnore;
95	    }
96	    if (options.customIgnoreFilePaths) {
97	      this.defaultFilterFileOptions.customIgnoreFilePaths =
98	        options.customIgnoreFilePaths;
99	    }
100	  }
101	
102	  /**
103	   * Filters a list of file paths based on ignore rules
104	   */
105	  filterFiles(filePaths: string[], options: FilterFilesOptions = {}): string[] {
106	    const {
107	      respectGitIgnore = this.defaultFilterFileOptions.respectGitIgnore,
108	      respectGeminiIgnore = this.defaultFilterFileOptions.respectGeminiIgnore,
109	    } = options;
110	    return filePaths.filter((filePath) => {
111	      if (
112	        respectGitIgnore &&
113	        respectGeminiIgnore &&
114	        this.combinedIgnoreFilter
115	      ) {
116	        return !this.combinedIgnoreFilter.isIgnored(filePath);
117	      }
118	
119	      // Always respect custom ignore filter if provided
120	      if (this.customIgnoreFilter?.isIgnored(filePath)) {
121	        return false;
122	      }
123	
124	      if (respectGitIgnore && this.gitIgnoreFilter?.isIgnored(filePath)) {
125	        return false;
126	      }
127	      if (respectGeminiIgnore && this.geminiIgnoreFilter?.isIgnored(filePath)) {
128	        return false;
129	      }
130	      return true;
131	    });
132	  }
133	
134	  /**
135	   * Filters a list of file paths based on git ignore rules and returns a report
136	   * with counts of ignored files.
137	   */
138	  filterFilesWithReport(
139	    filePaths: string[],
140	    opts: FilterFilesOptions = {
141	      respectGitIgnore: true,
142	      respectGeminiIgnore: true,
143	    },
144	  ): FilterReport {
145	    const filteredPaths = this.filterFiles(filePaths, opts);
146	    const ignoredCount = filePaths.length - filteredPaths.length;
147	
148	    return {
149	      filteredPaths,
150	      ignoredCount,
151	    };
152	  }
153	
154	  /**
155	   * Unified method to check if a file should be ignored based on filtering options
156	   */
157	  shouldIgnoreFile(
158	    filePath: string,
159	    options: FilterFilesOptions = {},
160	  ): boolean {
161	    return this.filterFiles([filePath], options).length === 0;
162	  }
163	
164	  /**
165	   * Returns the list of ignore files being used (e.g. .geminiignore) excluding .gitignore.
166	   */
167	  getIgnoreFilePaths(): string[] {
168	    const paths: string[] = [];
169	    if (
170	      this.geminiIgnoreFilter &&
171	      this.defaultFilterFileOptions.respectGeminiIgnore
172	    ) {
173	      paths.push(...this.geminiIgnoreFilter.getIgnoreFilePaths());
174	    }
175	    if (this.customIgnoreFilter) {
176	      paths.push(...this.customIgnoreFilter.getIgnoreFilePaths());
177	    }
178	    return paths;
179	  }
180	
181	  /**
182	   * Returns all ignore files including .gitignore if applicable.
183	   */
184	  getAllIgnoreFilePaths(): string[] {
185	    const paths: string[] = [];
186	    if (
187	      this.gitIgnoreFilter &&
188	      this.defaultFilterFileOptions.respectGitIgnore
189	    ) {
190	      const gitIgnorePath = path.join(this.projectRoot, '.gitignore');
191	      if (fs.existsSync(gitIgnorePath)) {
192	        paths.push(gitIgnorePath);
193	      }
194	    }
195	    return paths.concat(this.getIgnoreFilePaths());
196	  }
197	}
