+      const gitignoreContent = `
+# Comment
+node_modules/
+*.log
+/dist
+.env
+`;
+      await createTestFile('.gitignore', gitignoreContent);
+
+      expect(parser.isIgnored(path.join('node_modules', 'some-lib'))).toBe(
